def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = next((r for r, row in enumerate(grid) if 2 in row), h)
    out = [row[:] for row in grid]

    # Every 4 falls one row, unless blocked by the barrier or grid edge.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 4:
                out[r][c] = 0
                if r + 1 < h and r + 1 != wall:
                    out[r + 1][c] = 4
                else:
                    out[r][c] = 4

                # When a falling 4 reaches the row immediately above the
                # barrier, it spreads diagonally upward.
                if r == wall - 2:
                    k = 1
                    while r + 1 - k >= 0:
                        rr = r + 1 - k
                        for cc in (c - k, c + k):
                            if 0 <= cc < w:
                                out[rr][cc] = 4
                        k += 1
    return out
